const ic=(n,c="i")=>`<svg class="${c}" viewBox="0 0 24 24" aria-hidden="true" focusable="false" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${ICP[n]}</svg>`;
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const LS=(k,d=null)=>{try{const v=localStorage.getItem('dw2_'+k);return v==null?d:JSON.parse(v)}catch(e){return d}},SV=(k,v)=>localStorage.setItem('dw2_'+k,JSON.stringify(v));
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const REG=()=>LS('region'),US=()=>REG()==='us';
const T=()=>US()?{box:'lunchbox',Box:'Lunchbox',tag:'Smart feeding for busy US families — “dabba” is Hindi for lunchbox.',cur:'$'}:{box:'dabba',Box:'Dabba',tag:'Everyday food answers for Indian families.',cur:'₹'};
const TYPES=()=>[['breakfast','Breakfast'],['lunchbox',T().Box],['snack','Snack'],['dinner','Dinner']];
const DAYS=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];
const DAY=Math.floor((Date.now()+19800000)/864e5);
const ans=()=>ANS.filter(a=>a.r==='b'||a.r===REG());
const recs=()=>RECIPES.filter(r=>r.r===REG());
const getA=id=>ANS.find(a=>a.id===id),getR=id=>RECIPES.find(r=>r.id===id);
const exps=()=>EXPERTS.slice().sort((a,b)=>US()?(a.region==='India')-(b.region==='India'):(a.region!=='India')-(b.region!=='India'));
const kids=()=>LS('kids',[]),goals=()=>LS('goals',[]);
const ALG=['peanut','tree nut','milk','egg','wheat/gluten','soy','sesame','fish'];
function recAllergens(r){const txt=r.ing.join(' ')+' '+r.name;const out=new Set();LABEL_RULES.filter(x=>x.c==='allergen').forEach(x=>{if(x.k.test(txt))out.add(x.t.replace('Allergen: ','').replace('fish/shellfish','fish'))});
 if(/paneer|curd|yogurt|ghee|cheese|milk|cream|ricotta|raita|chaas|kadhi|lassi/i.test(txt))out.add('milk');if(/atta|roti|paratha|bread|pasta|noodle|tortilla|rava|dalia|vermicelli|bagel|pita|bun|waffle|pancake|muffin|lasagna|spaghetti|cracker/i.test(txt)&&!r.tags.includes('gluten-free'))out.add('wheat/gluten');
 if(/peanut|podi/i.test(txt))out.add('peanut');if(/sunflower|seed butter/i.test(txt))out.delete('peanut');return[...out]}
function dietOK(r,diet){if(!diet||diet==='nonveg')return true;if(diet==='jain')return r.tags.includes('jain');if(diet==='egg')return r.tags.includes('veg')||r.tags.includes('egg')&&!r.tags.includes('non-veg');return r.tags.includes('veg')&&!r.tags.includes('egg')&&!r.tags.includes('non-veg')}
function fitFamily(r){const ks=kids();if(!ks.length)return{ok:true,flags:[]};const al=recAllergens(r);const flags=[];ks.forEach(k=>{(k.allergies||[]).forEach(x=>al.includes(x)&&flags.push(`${k.name}: ${x}`))});return{ok:ks.every(k=>dietOK(r,k.diet))&&!flags.length,flags,diet:ks.every(k=>dietOK(r,k.diet))}}
const src=a=>a.src.split(' ').map(k=>SRC[REG()][k]).filter(Boolean).map(s=>`<a href="${s[1]}" target="_blank" rel="noopener">${esc(s[0])}</a>`).join('<br>');
const SYN={anda:'egg',doodh:'milk',dahi:'curd',yoghurt:'yogurt',nachni:'ragi',tiffin:'dabba',lunchbox:'dabba',anemia:'iron',anaemia:'iron',fussy:'picky',soda:'soft',namak:'salt',chawal:'rice',kela:'banana',palak:'spinach',gajar:'carrot',aloo:'potato',murgi:'chicken',machli:'fish',badam:'almonds',fiber:'fibre',color:'colour',candy:'sweets'};
function score(text,q){const h=text.toLowerCase();let s=0;q.forEach(w=>{const alts=[w,SYN[w]].filter(Boolean);if(alts.some(x=>h.includes(x)))s+=w.length>2?2:1});return s}
function searchAll(q){const ws=q.toLowerCase().split(/\s+/).filter(Boolean);if(!ws.length)return[];const out=[];
 ans().forEach(a=>{const s=score(a.q+' '+a.syn+' '+CATS[a.cat],ws);s&&out.push({s:s+1,t:'Answer',h:'#/a/'+a.id,l:a.q,d:a.short})});
 recs().forEach(r=>{const s=score(r.name+' '+r.ing.join(' ')+' '+r.tags.join(' ')+' '+r.type,ws);s&&out.push({s,t:'Recipe',h:'#/r/'+r.id,l:r.name,d:r.mins+' min · '+r.type})});
 GUIDES.forEach(g=>{const s=score(g.title+' '+g.steps.map(x=>x.join(' ')).join(' '),ws);s&&out.push({s:s+1,t:'Guide',h:'#/g/'+g.id,l:g.title,d:g.steps.length+' steps'})});
 HEAL.forEach(h=>{const f=(US()?h.us:h.in);if(!f.length)return;const s=score(h.t+' '+f.join(' ')+' '+h.g+' heal sick recovery',ws);s&&out.push({s:s+1,t:'Heal',h:'#/heal/s/'+h.id,l:h.t,d:f[0]})});
 [['When to eat what — time of day','#/heal/day','time of day breakfast bedtime after school before sport'],['Seasonal foods','#/heal/season','season summer winter monsoon fall spring']].forEach(([l,h,k])=>{const s=score(l+' '+k,ws);s&&out.push({s:s+2,t:'Heal',h,l,d:''})});
 EXPERTS.forEach(e=>{const s=score(e.name+' '+e.focus+' '+e.role,ws);s&&out.push({s,t:'Expert',h:'#/x/'+e.id,l:e.name,d:e.role})});
 [['Label decoder','#/tools/label','label ingredients additives decoder'],['Choking checker','#/tools/choke','choking safety age'],['Lunchbox builder','#/lunchbox','lunchbox dabba builder balance'],['Weekly planner','#/week','planner week plan'],['Shopping list','#/shop','shopping grocery list']].forEach(([l,h,k])=>{const s=score(l+' '+k,ws);s&&out.push({s:s+2,t:'Tool',h,l,d:''})});
 return out.sort((a,b)=>b.s-a.s)}
/* ---------- UI helpers ---------- */
let undoFn=null;
function toast(msg,undo){const t=$('#toast');t.innerHTML=esc(msg)+(undo?' <button class="link" id="undo">Undo</button>':'');t.className='show';undoFn=undo;if(undo)$('#undo').onclick=()=>{undo();t.className='';render()};clearTimeout(t._t);t._t=setTimeout(()=>t.className='',4000)}
function saved(){return LS('saved',{})} // {collection:[ids "a:id"/"r:id"]}
function isSaved(key){return Object.values(saved()).some(l=>l.includes(key))}
function toggleSave(key,col='Favourites'){const s=saved();if(isSaved(key)){const prev=JSON.stringify(s);Object.keys(s).forEach(c=>s[c]=s[c].filter(x=>x!==key));SV('saved',s);toast('Removed from saved',()=>SV('saved',JSON.parse(prev)))}else{(s[col]=s[col]||[]).push(key);SV('saved',s);toast('Saved to '+col)}render()}
function share(title){const url=location.href;if(navigator.share)navigator.share({title,url}).catch(()=>{});else navigator.clipboard?.writeText(url).then(()=>toast('Link copied'),()=>toast('Copy this link: '+url))}
var chip=(on,label,act,extra='')=>`<button class="chip${on?' on':''}" aria-pressed="${!!on}" onclick="${act}" ${extra}>${label}</button>`;
var crumbs=l=>`<nav class="crumbs" aria-label="Breadcrumb">${l.map((x,i)=>i<l.length-1?`<a href="${x[1]}">${esc(x[0])}</a><span aria-hidden="true">›</span>`:`<span aria-current="page">${esc(x[0])}</span>`).join('')}</nav>`;
var aCard=a=>`<a class="card tap" href="#/a/${a.id}"><div class="meta"><span class="tag">${CATS[a.cat]}</span>${a.safety&&a.safety!=='—'?'<span class="tag warnt">Safety note</span>':''}</div><h3>${esc(a.q)}</h3><p class="mute">${esc(a.short)}</p></a>`;
function rCard(r){const f=fitFamily(r);return`<a class="card tap rcard" href="#/r/${r.id}"><div class="rimg t-${r.type}" aria-hidden="true">${r.name[0]}</div><div><h3>${esc(r.name)}</h3><p class="mute">${r.mins?r.mins+' min · ':''}serves ${r.serves} · ${r.tags.slice(0,3).join(' · ')}</p>${f.flags.length?`<span class="tag bad">Allergen: ${esc(f.flags.join(', '))}</span>`:''}${kids().length&&!f.diet?'<span class="tag warnt">Diet mismatch</span>':''}</div></a>`}
var empty=(icon,title,body,cta='')=>`<div class="empty"><div class="eicon">${ic(icon)}</div><h3>${title}</h3><p class="mute">${body}</p>${cta}</div>`;
/* ---------- Views ---------- */
const V={};
V.onboard=(step='1')=>{step=+step;const rawDraft=LS('draftKids',null);const baseKids=kids();const rawKids=Array.isArray(rawDraft)?rawDraft:(Array.isArray(baseKids)&&baseKids.length?baseKids:[{name:'',age:'4-8y',diet:'veg',allergies:[]}]);const k=rawKids.map(c=>({name:String(c?.name||''),age:String(c?.age||'4-8y'),diet:String(c?.diet||'veg'),allergies:Array.isArray(c?.allergies)?c.allergies:[]}));const g=Array.isArray(goals())?goals():[];
 const dots=`<div class="dots">${[1,2,3].map(i=>`<span class="${i<=step?'on':''}"></span>`).join('')}</div>`;
 if(step===1)return`<div class="onb">${dots}<div class="brandmark">dabba<i>wise</i></div><h1>Where are you feeding kids?</h1><p class="mute">Sets foods, school notes and official sources. You can change it anytime.</p>
 <button class="card tap big" onclick="SV('region','in');go('#/onboard/2')"><span class="flag">IN</span><div><h3>India</h3><p class="mute">Dabba ideas · Indian foods · ICMR-NIN, FSSAI, IAP</p></div></button>
 <button class="card tap big" onclick="SV('region','us');go('#/onboard/2')"><span class="flag">US</span><div><h3>United States</h3><p class="mute">Lunchbox ideas · US foods · USDA, FDA, AAP, CDC</p></div></button>
 <button class="link" onclick="SV('region',REG()||'in');SV('onboarded',1);go('#/today')">Skip — just browse</button></div>`;
 if(step===2)return`<div class="onb">${dots}<h1>Who are you feeding?</h1><p class="mute">Optional. Stored only on this device. Used to personalise Today, filter meals and flag allergens.</p>
 ${k.map((c,i)=>`<fieldset class="card"><legend>Child ${i+1}</legend><label>Name or nickname<input value="${esc(c.name)}" oninput="dk(${i},'name',this.value)" placeholder="e.g. Aarav"></label>
 <label>Age<select onchange="dk(${i},'age',this.value)">${AGES.map(a=>`<option value="${a[0]}"${a[0]===c.age?' selected':''}>${a[1]}</option>`).join('')}</select></label>
 <label>Diet<select onchange="dk(${i},'diet',this.value)">${[['veg','Vegetarian'],['egg','Vegetarian + egg'],['jain','Jain'],['nonveg','Non-vegetarian']].map(d=>`<option value="${d[0]}"${d[0]===c.diet?' selected':''}>${d[1]}</option>`).join('')}</select></label>
 <div class="lbl">Allergies</div><div class="chips wrap">${ALG.map(x=>chip(c.allergies.includes(x),x,`dkA(${i},'${x}')`)).join('')}</div>${k.length>1?`<button class="link" onclick="dkDel(${i})">Remove</button>`:''}</fieldset>`).join('')}
 <button onclick="dkAdd()">+ Add another child</button><div class="row end"><button class="link" onclick="go('#/onboard/3')">Skip</button><button class="pri" onclick="SV('kids',LS('draftKids',[]).filter(c=>c.name.trim()));go('#/onboard/3')">Continue</button></div></div>`;
 return`<div class="onb">${dots}<h1>What would help most?</h1><p class="mute">Pick any. We’ll shape Today around them.</p><div class="chips wrap">${[['picky','Picky eating'],['iron','Iron & nutrients'],['lunchbox','Easier '+T().box+'es'],['labels','Reading labels'],['first-foods','Starting solids'],['sports','Sports & activity'],['budget','Eating well on a budget']].map(([id,l])=>chip(g.includes(id),l,`tg('${id}')`)).join('')}</div>
 <div class="row end"><button class="pri" onclick="SV('onboarded',1);go('#/today');toast('You’re all set')">Start using Dabbawise</button></div></div>`};
function dk(i,f,v){const k=LS('draftKids',kids().length?kids():[{name:'',age:'4-8y',diet:'veg',allergies:[]}]);k[i][f]=v;SV('draftKids',k)}
function dkA(i,x){const k=LS('draftKids',kids().length?kids():[{name:'',age:'4-8y',diet:'veg',allergies:[]}]);const a=k[i].allergies;k[i].allergies=a.includes(x)?a.filter(y=>y!==x):[...a,x];SV('draftKids',k);render()}
function dkAdd(){const k=LS('draftKids',kids().length?kids():[{name:'',age:'4-8y',diet:'veg',allergies:[]}]);k.push({name:'',age:'1-3y',diet:'veg',allergies:[]});SV('draftKids',k);render()}
function dkDel(i){const k=LS('draftKids',[]);k.splice(i,1);SV('draftKids',k);render()}
function tg(id){const g=goals();SV('goals',g.includes(id)?g.filter(x=>x!==id):[...g,id]);render()}
const GOALMAP={picky:['picky','new-food','dabba-return','screen-eating'],iron:['iron','b12','vitd','calcium'],lunchbox:['dabba-balance','lunchbox-balance','dabba-fresh','nut-free-school'],labels:['label-read','added-sugar-label','claims','additives'],'first-foods':['first-foods','allergy-intro','choking','honey'],sports:['sports-day','hydration','sports-drinks'],budget:['budget','seasonal','frozen','shopping-list']};
V.today=()=>{const ks=kids(),g=goals();const pool=ans().filter(a=>a.cat!=='myths');let pick=g.flatMap(x=>GOALMAP[x]||[]).map(getA).filter(a=>a&&ans().includes(a));if(!pick.length)pick=pool;
 const q=pick[DAY%pick.length];const rs=recs().filter(r=>fitFamily(r).ok);const meal=(rs.length?rs:recs())[DAY%(rs.length||recs().length)];const myths=ans().filter(a=>a.cat==='myths');const my=myths[DAY%myths.length];
 const acts=['Add one colour to today’s '+T().box+'.','Have one screen-free family meal.','Swap one packaged snack for fruit or a roasted snack.','Pair an iron-rich food with vitamin C today.','Let your child choose one vegetable this week.','Offer water before juice.','Let your child help prepare one thing today.'];
 const done=LS('done_'+DAY,false);const hr=new Date().getHours();const hello=hr<12?'Good morning':hr<17?'Good afternoon':'Good evening';
 const g0=GUIDES.find(x=>g.includes(x.id))||GUIDES[DAY%GUIDES.length];
 return`<header class="phead"><p class="mute">${new Date().toLocaleDateString(undefined,{weekday:'long',day:'numeric',month:'long'})}</p><h1>${hello}${ks.length?', '+esc(ks.map(k=>k.name).join(' & '))+'’s family':''}.</h1><p class="mute">${T().tag}</p></header>
 <section class="ritual" aria-label="Today’s three-minute ritual"><div class="rhead"><b>Today in 3 minutes</b><span class="mute">No streaks. Just one useful thing a day.</span></div>
 <a class="card hero tap" href="#/a/${q.id}"><span class="kicker">1 · Today’s question${g.length?' · for your goals':''}</span><h2>${esc(q.q)}</h2><p>${esc(q.short)}</p><span class="more">Read the full answer →</span></a>
 <div class="grid2"><a class="card tap" href="#/r/${meal.id}"><span class="kicker">2 · Meal idea</span><h3>${esc(meal.name)}</h3><p class="mute">${meal.mins} min · ${TYPES().find(t=>t[0]===meal.type)[1]}${ks.length?' · fits your family':''}</p></a>
 <a class="card tap" href="#/a/${my.id}"><span class="kicker">3 · Myth check</span><h3>${esc(my.q.replace('Myth: ',''))}</h3><p class="mute">${esc(my.short)}</p></a></div>
 <div class="card action"><span class="kicker">4 · One small action</span><h3>${acts[DAY%acts.length]}</h3><button class="${done?'':'pri'}" aria-pressed="${done}" onclick="SV('done_'+DAY,${!done});render();${done?'':"toast('Nice. See you tomorrow.')"}">${done?ic('check')+'Done today':'Mark done'}</button></div></section>
 <h2 class="sec">Continue learning</h2><a class="card tap guide" href="#/g/${g0.id}"><span class="kicker">Guide · ${g0.steps.length} steps · ${g0.mins} min</span><h3>${esc(g0.title)}</h3><div class="prog"><span style="width:${(LS('gp_'+g0.id,0))/g0.steps.length*100}%"></span></div></a>
 <h2 class="sec">Daily Food Note</h2><div class="card">${LS('note')?`<p>Subscribed as ${esc(LS('note'))}. <button class="link" onclick="SV('note',null);render()">Unsubscribe</button></p>`:`<p class="mute">One useful food note each morning. Demo only — no email is sent.</p><form class="row" onsubmit="event.preventDefault();SV('note',this.e.value);toast('Subscribed (demo)');render()"><label class="sr" for="em">Email</label><input id="em" name="e" type="email" required placeholder="you@email.com"><button class="pri">Join</button></form>`}</div>
 <h2 class="sec">Parent Table</h2><div class="card"><p class="mute">Questions parents are asking this week</p>${ans().filter(a=>['dabba-return','picky','breakfast-skip','grandparents','halloween','screen-eating','budget'].includes(a.id)).slice(0,4).map(a=>`<a class="lrow" href="#/a/${a.id}"><span>${esc(a.q)}</span>${ic('right')}</a>`).join('')}<p class="mute small">Moderated community discussion is planned; expert-reviewed answers will be pinned.</p></div>
 <h2 class="sec">Tools</h2><div class="grid2 tools">${[['#/lunchbox','box',T().Box+' builder'],['#/tools/label','scan','Label decoder'],['#/tools/choke','shield','Choking checker'],['#/heal','leaf','Foods that heal']].map(x=>`<a class="card tap tool" href="${x[0]}"><span class="ticon">${ic(x[1])}</span>${x[2]}</a>`).join('')}</div>`};
V.explore=(sub,cat)=>{const cs=Object.keys(CATS);const sel=sub==='c'?cat:null;const list=sel?ans().filter(a=>a.cat===sel):[];
 if(sel)return crumbs([['Explore','#/explore'],[CATS[sel]]])+`<h1>${CATS[sel]}</h1><p class="mute">${list.length} answers</p>${list.map(aCard).join('')}`;
 return`<h1>Explore</h1><button class="searchbtn" onclick="openK()" aria-label="Search everything">${ic('search')}<span class="ph">Ask anything — ${US()?'juice boxes, nut-free lunch':'anda, paneer, tiffin'}</span><kbd>⌘K</kbd></button>
 <a class="card tap lcard" href="#/experts"><span class="ticon">${ic('users')}</span><span class="grow"><b>Hear from the Experts</b><small class="mute">20 profiles · public work, summarised</small></span>${ic('right')}</a><div class="grid2 xgrid">${[['#/guides','book','Guides'],['#/myths','leaf','Myths'],['#/tools','tools','Tools'],['#/saved','star','Saved']].map(x=>`<a class="card tap lcard" href="${x[0]}"><span class="ticon">${ic(x[1])}</span><b class="grow">${x[2]}</b></a>`).join('')}</div><h2 class="sec">Topics</h2><div class="grid2">${cs.map(c=>{const n=ans().filter(a=>a.cat===c).length;return`<a class="card tap topic" href="#/explore/c/${c}"><h3>${CATS[c]}</h3><p class="mute">${n} answers</p></a>`}).join('')}</div>
 <h2 class="sec">Learn step by step</h2>${GUIDES.filter(g=>g.id!=='dabba'||!US()).map(g=>`<a class="card tap" href="#/g/${g.id}"><span class="kicker">Guide · ${g.steps.length} steps</span><h3>${esc(g.title)}</h3></a>`).join('')}
 <h2 class="sec">Myth library</h2><a class="card tap" href="#/myths"><h3>${ans().filter(a=>a.cat==='myths').length} common food myths, checked</h3><p class="mute">Ghee, brown bread, sugar & hyperactivity…</p></a>`};
V.myths=()=>crumbs([['Explore','#/explore'],['Myths']])+`<h1>Myth library</h1>${ans().filter(a=>a.cat==='myths').map(a=>`<details class="card myth"><summary><span class="tag bad">Myth</span> ${esc(a.q.replace('Myth: ',''))}</summary><p><b>What the evidence suggests:</b> ${esc(a.short)}</p><a href="#/a/${a.id}">Full answer & sources →</a></details>`).join('')}`;
V.a=id=>{const a=getA(id);if(!a)return empty('search','Answer not found','It may not exist in this region.','<a class="btn" href="#/explore">Explore</a>');
 const ks=kids();const myAges=ks.map(k=>k.age);const rel=ans().filter(x=>x.cat===a.cat&&x.id!==a.id).slice(0,4);const todo=a.todo[REG()]||a.todo.in;
 const ages=a.ages?`<section class="part"><h2><span>3</span>By age</h2>${a.ages_generic?'<p class="mute small">General age guidance for this topic.</p>':''}<div class="ages">${AGES.map(([k,l])=>`<div class="age${myAges.includes(k)?' mine':''}"><b>${l}${myAges.includes(k)?' · your child':''}</b><p>${esc(a.ages[k])}</p></div>`).join('')}</div></section>`:`<section class="part"><h2><span>3</span>By age</h2><p class="mute">The advice above applies broadly across ages; check with your paediatrician for infants under 12 months.</p></section>`;
 const fb=LS('fb',{})[id];
 return crumbs([['Explore','#/explore'],[CATS[a.cat],'#/explore/c/'+a.cat],['Answer']])+`<article class="answer"><div class="meta"><span class="tag">${CATS[a.cat]}</span><span class="tag evt">Evidence: ${a.ev}</span><span class="tag draft">Draft — pending expert review</span></div><h1>${esc(a.q)}</h1>
 <div class="actions"><button onclick="toggleSave('a:${id}')" aria-pressed="${isSaved('a:'+id)}">${ic('star',isSaved('a:'+id)?'i fill':'i')}${isSaved('a:'+id)?'Saved':'Save'}</button><button onclick="share(${JSON.stringify(a.q).replace(/"/g,'&quot;')})">${ic('share')}Share</button></div>
 <section class="part lead"><h2><span>1</span>Short answer</h2><p>${esc(a.short)}</p></section>
 <section class="part"><h2><span>2</span>Why</h2><p>${esc(a.why==='—'?'See the short answer and sources below.':a.why)}</p></section>${ages}
 <section class="part"><h2><span>4</span>What to do ${US()?'':'in an Indian kitchen'}</h2><p>${esc(todo||'—')}</p></section>
 <section class="part"><h2><span>5</span>Evidence type</h2><p><b>${a.ev}</b> — ${a.ev==='Official guidance'?'based on national or international public-health guidance.':a.ev==='Research evidence'?'based on published research findings.':'a cautious reading of guidance and common professional practice; not a formal guideline.'}</p></section>
 <section class="part"><h2><span>6</span>Safety note</h2>${a.safety&&a.safety!=='—'?`<div class="note warn" role="note">${ic('alert')}<span>${esc(a.safety)}</span></div>`:'<p class="mute">No specific safety concern for healthy children in usual amounts.</p>'}</section>
 <section class="part"><h2><span>7</span>Sources</h2><p>${src(a)}</p><p class="mute small">Links go to the organisation’s public pages. Specific section references will be added during expert review.</p></section>
 <section class="part"><h2><span>8</span>Review</h2><p><span class="tag draft">Draft</span> Reviewer: <i>to be assigned (qualified paediatric dietitian)</i> · Review date: <i>pending</i></p><p class="mute small">General information, not medical advice. Ask your paediatrician about your child’s specific needs.</p></section>
 <section class="part"><h2>Was this helpful?</h2>${fb?`<p class="mute">Thanks — feedback saved on this device${fb.err?' (error report noted)':''}.</p>`:`<div class="row"><button onclick="fbk('${id}',1)">${ic('up')}Yes</button><button onclick="fbk('${id}',0)">${ic('up','i flip')}No</button><button class="link" onclick="reportErr('${id}')">Report an error</button></div>`}</section>
 <h2 class="sec">Related questions</h2>${rel.map(aCard).join('')}</article>`};
function fbk(id,v,err){const f=LS('fb',{});f[id]={v,err,at:Date.now()};SV('fb',f);toast('Thanks for the feedback');render()}
function reportErr(id){modal(`<h2>Report an error</h2><p class="mute">What looks wrong? Saved on this device for the review team (prototype — nothing is sent).</p><label class="sr" for="et">Details</label><textarea id="et" rows="4"></textarea><div class="row end"><button onclick="closeM()">Cancel</button><button class="pri" onclick="fbk('${id}',0,document.getElementById('et').value||'flagged');closeM()">Submit</button></div>`)}
let MS={type:'all',diet:'family',tag:'',have:[]};
V.meals=()=>{let rs=recs();if(MS.type!=='all')rs=rs.filter(r=>r.type===MS.type);if(MS.diet==='family')rs=rs.filter(r=>fitFamily(r).ok);else if(MS.diet!=='all')rs=rs.filter(r=>dietOK(r,MS.diet));if(MS.tag)rs=rs.filter(r=>r.tags.includes(MS.tag)||(MS.tag==='quick'&&r.mins<=15));
 const ing=[...new Set(recs().flatMap(r=>r.ing.map(i=>i.replace(/^[\d\/\s.]+(cups?|tbsp|tsp|g|lb|can)?\s*/i,'').split(/[,(]/)[0].trim().toLowerCase())))].filter(x=>x.length>2&&x.length<22).sort();
 return`<h1>Meals</h1>
 <div class="chips">${chip(MS.type==='all','All',"MS.type='all';render()")}${TYPES().map(t=>chip(MS.type===t[0],t[1],`MS.type='${t[0]}';render()`)).join('')}</div>
 <div class="chips">${(kids().length?[['family','Fits my family']]:[]).concat([['all','Any diet'],['veg','Veg'],['egg','Veg + egg'],['jain','Jain'],['vegan','Vegan'],['nonveg','Non-veg']]).map(d=>chip(MS.diet===d[0],d[1],`MS.diet='${d[0]}';render()`)).join('')}</div>
 <div class="chips">${['quick','nut-free','gluten-free'].map(t=>chip(MS.tag===t,t==='quick'?'≤15 min':t,`MS.tag=MS.tag==='${t}'?'':'${t}';render()`)).join('')}</div>
 ${US()&&MS.type==='lunchbox'?'<div class="note">Many US schools are nut-free. Check your school’s policy — some also restrict seed butters.</div>':''}
 <div class="rgrid">${rs.map(rCard).join('')||empty('meal','No recipes match','Try removing a filter.',`<button onclick="MS={type:'all',diet:'all',tag:'',have:[]};render()">Clear filters</button>`)}</div>
 <h2 class="sec">Use what I have</h2><p class="mute">Tap ingredients in your kitchen — we’ll suggest recipes and list what’s missing.</p><div class="chips wrap">${ing.slice(0,60).map(i=>chip(MS.have.includes(i),esc(i),`hv('${i.replace(/'/g,"")}')`)).join('')}</div>
 <div id="sugg">${sugg()}</div>`};
function sugg(){if(!MS.have.length)return'';const out=recs().map(r=>{const n=r.ing.map(i=>i.toLowerCase());const h=n.filter(i=>MS.have.some(x=>i.includes(x)));return{r,h,miss:r.ing.filter((i,j)=>!h.includes(n[j])),s:h.length/n.length}}).filter(x=>x.h.length).sort((a,b)=>b.s-a.s).slice(0,6);
 return out.map(x=>`<div class="card"><a href="#/r/${x.r.id}"><h3>${esc(x.r.name)}</h3></a><div class="meter" aria-label="${Math.round(x.s*100)}% of ingredients"><span style="width:${x.s*100}%"></span></div><p class="mute small">${x.miss.length?'Missing: '+esc(x.miss.join(', ')):'You have everything'}</p>${x.miss.length?`<button onclick='addShop(${JSON.stringify(x.miss).replace(/'/g,"&#39;")})'>+ Add missing to list</button>`:''}</div>`).join('')}
function hv(i){MS.have=MS.have.includes(i)?MS.have.filter(x=>x!==i):[...MS.have,i];render()}
V.r=id=>{const r=getR(id);if(!r)return empty('meal','Recipe not found','','<a class="btn" href="#/meals">All meals</a>');const f=fitFamily(r),al=recAllergens(r);
 return crumbs([['Meals','#/meals'],[r.name]])+`<article><div class="rimg big t-${r.type}" aria-hidden="true">${r.name[0]}</div><div class="meta">${r.tags.map(t=>`<span class="tag">${t}</span>`).join('')}</div><h1>${esc(r.name)}</h1><p class="mute">${r.mins?r.mins+' min':'No cooking'} · serves ${r.serves} · ${TYPES().find(t=>t[0]===r.type)[1]}</p>
 ${f.flags.length?`<div class="note bad" role="alert">${ic('alert')} Allergen alert for ${esc(f.flags.join(', '))}</div>`:''}${al.length?`<p class="small mute">Contains or may contain: ${al.join(', ')}. Always check your own ingredients.</p>`:''}
 <div class="actions"><button onclick="toggleSave('r:${id}')">${ic('star',isSaved('r:'+id)?'i fill':'i')}${isSaved('r:'+id)?'Saved':'Save'}</button><button onclick="pickDay('${id}')">${ic('cal')}Add to week</button><button onclick='addShop(${JSON.stringify(r.ing).replace(/'/g,"&#39;")})'>${ic('cart')}Shopping list</button><button onclick="share('${esc(r.name)}')">${ic('share')}Share</button></div>
 <div class="grid2 rec"><section class="card"><h2>Ingredients</h2><ul class="checks">${r.ing.map(i=>`<li><label><input type="checkbox"> ${esc(i)}</label></li>`).join('')}</ul></section>
 <section class="card"><h2>Steps</h2><ol>${r.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol></section></div>
 <div class="grid2"><div class="card"><span class="kicker">Kid tip</span><p>${esc(r.tip)}</p></div><div class="card"><span class="kicker">Storage & transport</span><p>${esc(r.store)}</p></div></div>
 <p class="mute small">Recipe draft — adapt textures for your child’s age; see the Choking checker for under-5s.</p></article>`};
/* Planner */
const plan=()=>LS('plan_'+REG(),{});
function pickDay(id){modal(`<h2>Add to which day?</h2><div class="chips wrap">${DAYS.map(d=>`<button class="chip" onclick="addPlan('${d}','${id}');closeM()">${d}</button>`).join('')}</div>`)}
function addPlan(d,id){const p=plan();(p[d]=p[d]||[]).push(id);SV('plan_'+REG(),p);toast('Added to '+d)}
function rmPlan(d,i){const p=plan(),prev=JSON.stringify(p);p[d].splice(i,1);SV('plan_'+REG(),p);toast('Removed',()=>SV('plan_'+REG(),JSON.parse(prev)));render()}
function movePlan(fd,i,td){const p=plan();const[id]=p[fd].splice(i,1);(p[td]=p[td]||[]).push(id);SV('plan_'+REG(),p);render()}
function autoWeek(){const prev=JSON.stringify(plan());const rs=recs().filter(r=>fitFamily(r).ok);const by=t=>{const l=rs.filter(r=>r.type===t);return l.length?l:recs().filter(r=>r.type===t)};const p={};
 DAYS.forEach((d,i)=>{p[d]=['breakfast','lunchbox','snack','dinner'].map((t,j)=>{const l=by(t);return l[(i*3+j*7+DAY)%l.length].id}).filter((x,j)=>!(i>4&&j===1))});SV('plan_'+REG(),p);toast('Week generated from your profile',()=>SV('plan_'+REG(),JSON.parse(prev)));render()}
function weekToShop(){const ids=Object.values(plan()).flat();addShop(ids.flatMap(id=>getR(id)?.ing||[]))}
V.week=()=>{const p=plan();const n=Object.values(p).flat().length;
 return`<div class="row between"><h1>My Week</h1><div class="row"><button onclick="autoWeek()">${ic('spark')}Auto-plan</button><button class="icon" onclick="window.print()" aria-label="Print week">${ic('print')}</button></div></div>
 <div class="subnav">${[['#/week','Plan'],['#/lunchbox',T().Box],['#/shop','Shopping'],['#/saved','Saved']].map(x=>`<a href="${x[0]}"${x[0]==='#/week'?' aria-current="page"':''}>${x[1]}</a>`).join('')}</div>
 ${n?'<p class="mute small">Drag meals between days (or use the move button).</p>':empty('cal','Your week is empty','Auto-plan a balanced week from your family profile, or add meals from recipes.',`<button class="pri" onclick="autoWeek()">${ic('spark')}Auto-plan my week</button>`)}
 <div class="week">${DAYS.map(d=>`<section class="day card" data-day="${d}" ondragover="event.preventDefault();this.classList.add('over')" ondragleave="this.classList.remove('over')" ondrop="drop(event,'${d}')"><h3>${d}</h3>${(p[d]||[]).map((id,i)=>{const r=getR(id);return r?`<div class="pchip t-${r.type}" draggable="true" ondragstart="event.dataTransfer.setData('text','${d}|${i}')"><a href="#/r/${id}">${esc(r.name)}</a><button class="ib" aria-label="Move ${esc(r.name)}" onclick="moveAsk('${d}',${i})">${ic('move')}</button><button class="ib" aria-label="Remove ${esc(r.name)}" onclick="rmPlan('${d}',${i})">${ic('x')}</button></div>`:''}).join('')||'<p class="mute small">—</p>'}</section>`).join('')}</div>
 ${n?`<button onclick="weekToShop()">${ic('cart')}Add whole week to shopping list</button>`:''}`};
function drop(e,d){e.preventDefault();const[fd,i]=e.dataTransfer.getData('text').split('|');if(fd&&fd!==d)movePlan(fd,+i,d)}
function moveAsk(d,i){modal(`<h2>Move to…</h2><div class="chips wrap">${DAYS.filter(x=>x!==d).map(x=>`<button class="chip" onclick="movePlan('${d}',${i},'${x}');closeM()">${x}</button>`).join('')}</div>`)}
/* Lunchbox builder */
const LB={main:'',side:'',fruit:'',protein:''};
const LBO=()=>US()?{main:['Whole-wheat sandwich','Tortilla wrap','Pasta salad','Rice bowl','Mini bagel','Quesadilla'],protein:['Turkey slices','Cheese cubes','Hard-boiled egg','Hummus','Black beans','Sunflower seed butter','Yogurt tube'],side:['Carrot sticks (steamed for <4)','Cucumber slices','Cherry tomatoes (quartered)','Snap peas','Bell pepper strips','Edamame'],fruit:['Apple slices','Quartered grapes','Berries','Orange segments','Banana','Melon cubes']}
 :{main:['Paratha','Roti roll','Mini idli','Veg pulao','Lemon rice','Poha','Chilla','Dosa / uttapam'],protein:['Paneer','Curd dip','Boiled egg','Dal / sambar','Rajma / chole','Sprouts (steamed)','Peanut chutney'],side:['Cucumber slices','Carrot (grated/steamed)','Sabzi','Corn','Beans poriyal','Kachumber'],fruit:['Apple slices','Banana','Guava','Orange segments','Papaya','Pomegranate']};
V.lunchbox=()=>{const o=LBO();const groups={grain:!!LB.main,protein:!!LB.protein,veg:!!LB.side,fruit:!!LB.fruit,dairy:/paneer|curd|cheese|yogurt/i.test(LB.protein)};const sc=Object.values(groups).filter(Boolean).length;
 const nut=/peanut|seed butter/i.test(LB.protein);
 return crumbs([['My Week','#/week'],[T().Box+' builder']])+`<h1>${T().Box} builder</h1><p class="mute">Pick one from each row. The meter shows how many food groups you’ve covered.</p>
 <div class="card balance"><div class="row between"><b>Balance</b><span>${sc}/5 food groups</span></div><div class="meter big" role="meter" aria-valuemin="0" aria-valuemax="5" aria-valuenow="${sc}" aria-label="Balance"><span style="width:${sc*20}%"></span></div><div class="chips">${Object.entries(groups).map(([k,v])=>`<span class="tag ${v?'':'off'}">${v?'✓ ':''}${k}</span>`).join('')}</div>
 ${sc>=4?'<p>Great balance. Add water and you’re set.</p>':'<p class="mute">Tip: a grain + protein + veg + fruit covers most bases.</p>'}${nut&&US()?'<div class="note warn">Check your school’s nut/seed policy.</div>':''}</div>
 ${Object.entries({main:'Main (grain)',protein:'Protein',side:'Vegetable',fruit:'Fruit'}).map(([k,l])=>`<h2 class="sec">${l}</h2><div class="chips wrap">${o[k].map(x=>chip(LB[k]===x,esc(x),`LB.${k}=LB.${k}==='${x}'?'':'${x}';render()`)).join('')}</div>`).join('')}
 <div class="row end"><button onclick="Object.keys(LB).forEach(k=>LB[k]=Object.values(LBO())[0]&&LBO()[k][Math.floor(Math.random()*LBO()[k].length)]);render()">${ic('shuffle')}Surprise me</button><button class="pri" ${sc?'':'disabled'} onclick="saveBox()">Save to rotation</button></div>
 <h2 class="sec">Saved ${T().box} rotation</h2>${(LS('boxes_'+REG(),[])).map((b,i)=>`<div class="card row between"><span>${esc(Object.values(b).filter(Boolean).join(' + '))}</span><button class="ib" aria-label="Remove" onclick="rmBox(${i})">${ic('x')}</button></div>`).join('')||'<p class="mute">No saved combinations yet.</p>'}`};
function saveBox(){const b=LS('boxes_'+REG(),[]);b.push({...LB});SV('boxes_'+REG(),b);toast('Saved to rotation')}
function rmBox(i){const b=LS('boxes_'+REG(),[]),prev=JSON.stringify(b);b.splice(i,1);SV('boxes_'+REG(),b);toast('Removed',()=>SV('boxes_'+REG(),JSON.parse(prev)));render()}
/* Shopping */
function addShop(items){const s=LS('shop_'+REG(),[]);let n=0;items.forEach(i=>{if(!s.some(x=>x.t.toLowerCase()===i.toLowerCase())){s.push({t:i,d:false});n++}});SV('shop_'+REG(),s);toast(n?`Added ${n} item${n>1?'s':''} to shopping list`:'Already on your list')}
const aisle=t=>Object.keys(AISLE).find(k=>AISLE[k].test(t));
V.shop=()=>{const s=LS('shop_'+REG(),[]);const g={};s.forEach((x,i)=>{(g[aisle(x.t)]=g[aisle(x.t)]||[]).push([x,i])});
 return crumbs([['My Week','#/week'],['Shopping list']])+`<div class="row between"><h1>Shopping list</h1>${s.some(x=>x.d)?'<button onclick="clearDone()">Clear checked</button>':''}</div>
 <form class="row" onsubmit="event.preventDefault();addShop([this.i.value]);this.reset();render()"><label class="sr" for="si">Add item</label><input id="si" name="i" required placeholder="Add an item…"><button class="pri">Add</button></form>
 ${s.length?Object.keys(AISLE).filter(k=>g[k]).map(k=>`<h2 class="sec">${k}</h2><div class="card">${g[k].map(([x,i])=>`<label class="lrow check${x.d?' done':''}"><input type="checkbox" ${x.d?'checked':''} onchange="tick(${i})"> <span>${esc(x.t)}</span></label>`).join('')}</div>`).join(''):empty('cart','Your list is empty','Add items from recipes, “Use what I have”, or your weekly plan.','<a class="btn" href="#/meals">Browse meals</a>')}`};
function tick(i){const s=LS('shop_'+REG(),[]);s[i].d=!s[i].d;SV('shop_'+REG(),s);render()}
function clearDone(){const s=LS('shop_'+REG(),[]),prev=JSON.stringify(s);SV('shop_'+REG(),s.filter(x=>!x.d));toast('Cleared checked items',()=>SV('shop_'+REG(),JSON.parse(prev)));render()}
V.saved=()=>{const s=saved();const cols=Object.keys(s).filter(c=>s[c].length);
 return crumbs([['My Week','#/week'],['Saved']])+`<h1>Saved</h1>${cols.length?cols.map(c=>`<h2 class="sec">${esc(c)} <span class="mute">(${s[c].length})</span></h2>${s[c].map(k=>{const[t,id]=k.split(':');if(t==='h'){const h=HEAL.find(z=>z.id===id);return h?`<a class="card tap lcard" href="#/heal/s/${h.id}"><span class="ticon">${ic('leaf')}</span><b class="grow">${h.t}</b>${ic('right')}</a>`:''}const x=t==='a'?getA(id):getR(id);return x?(t==='a'?aCard(x):rCard(x)):''}).join('')}`).join(''):empty('star','Nothing saved yet','Tap Save on any answer or recipe.','<a class="btn" href="#/explore">Explore answers</a>')}`};
/* Guides */
V.guides=()=>crumbs([['Explore','#/explore'],['Guides']])+`<h1>Guides</h1>${GUIDES.map(g=>`<a class="card tap" href="#/g/${g.id}"><span class="kicker">${g.steps.length} steps · ${g.mins} min</span><h3>${esc(g.title)}</h3><div class="prog"><span style="width:${LS('gp_'+g.id,0)/g.steps.length*100}%"></span></div></a>`).join('')}`;
V.g=(id,s)=>{const g=GUIDES.find(x=>x.id===id);if(!g)return empty('book','Guide not found','','');const saved0=LS('gp_'+id,0);const i=s!=null?Math.min(+s,g.steps.length):(saved0<g.steps.length?saved0:0);
 if(i>=g.steps.length)return crumbs([['Guides','#/guides'],[g.title]])+`<div class="card center"><div class="eicon">${ic('check')}</div><h1>Guide complete</h1><p class="mute">Keep going with related answers:</p></div>${g.ans.map(getA).filter(a=>a&&ans().includes(a)).map(aCard).join('')}<button onclick="SV('gp_${id}',0);go('#/g/${id}/0')">Restart guide</button>`;
 const st=g.steps[i];return crumbs([['Guides','#/guides'],[g.title]])+`<div class="prog"><span style="width:${i/g.steps.length*100}%"></span></div><p class="mute">Step ${i+1} of ${g.steps.length}</p><div class="card step"><h1>${esc(st[0])}</h1><p class="lead">${esc(st[1])}</p></div>
 <div class="row between">${i?`<a class="btn" href="#/g/${id}/${i-1}">← Back</a>`:'<span></span>'}<a class="btn pri" href="#/g/${id}/${i+1}" onclick="SV('gp_${id}',${i+1})">${i===g.steps.length-1?'Finish':'Next →'}</a></div><p class="mute small">Draft learning module — pending expert review. Sources: see linked answers.</p>`};
/* Experts */
const XT={picky:['Picky eating','#/g/picky'],growth:['Growth','#/explore/c/growth'],structure:['Mealtime structure','#/a/meal-timing'],early:['First foods','#/g/first-foods'],micro:['Micronutrients','#/g/iron'],foodenv:['Food environment','#/explore/c/shopping'],lunchbox:['Lunchboxes','#/lunchbox'],indian:['Indian foods','#/explore/c/foods'],labels:['Labels','#/g/labels']};
let XF='All';
V.experts=()=>{const l=exps().filter(e=>XF==='All'||e.region===XF||(XF==='Global'&&e.region!=='India'));
 return`<h1>Hear from the Experts</h1><p class="mute">Curated summaries of public work by 20 child-nutrition and feeding experts, linked to original sources.</p>
 <div class="note" role="note"><b>Inclusion ≠ endorsement.</b> These experts have not reviewed or endorsed Dabbawise. We summarise public work only and never invent quotes. Qualifications and scope differ — check each profile.</div>
 <div class="chips">${['All',US()?'Global':'India',US()?'India':'Global'].map(c=>chip(XF===c,c,`XF='${c}';render()`)).join('')}</div>
 <div class="rgrid">${l.map(e=>`<a class="card tap xcard" href="#/x/${e.id}"><div class="av" aria-hidden="true">${e.name.replace('Dr. ','').split(' ').map(w=>w[0]).slice(0,2).join('')}</div><div><h3>${esc(e.name)}</h3><p class="mute small">${esc(e.role)} · ${e.region}</p><p class="small">${esc(e.focus)}</p></div></a>`).join('')}</div>`};
V.x=id=>{const e=EXPERTS.find(x=>x.id===id);if(!e)return empty('users','Expert not found','','');const rel=e.topics.map(t=>XT[t]).filter(Boolean);
 return crumbs([['Experts','#/experts'],[e.name]])+`<div class="xhead"><div class="av big" aria-hidden="true">${e.name.replace('Dr. ','').split(' ').map(w=>w[0]).slice(0,2).join('')}</div><div><h1>${esc(e.name)}</h1><p class="mute">${esc(e.role)} · ${e.region}</p></div></div>
 <div class="card"><span class="kicker">Focus</span><p>${esc(e.focus)}</p><span class="kicker">Summary of public work</span><p>${esc(e.about)}</p><a class="btn" href="${e.url}" target="_blank" rel="noopener">Official public resource</a></div>
 <h2 class="sec">Related topics in Dabbawise</h2><div class="chips wrap">${rel.map(([l,h])=>`<a class="chip" href="${h}">${l}</a>`).join('')}</div>
 <div class="note">Summaries are paraphrased from public material and pending verification. No quotes are attributed. Where expert approaches differ, Dabbawise answers point to official guidance and show the evidence type.</div>`};
/* Tools */
V.tools=(t)=>{if(t==='label')return crumbs([['Tools','#/tools'],['Label decoder']])+`<h1>Label decoder</h1><p class="mute">Paste an ingredient list. We flag added sugars, sodium, refined flour, fats, colours, sweeteners, caffeine and common allergens using ${US()?'FDA':'FSSAI'} terms.</p>
 <label class="sr" for="lab">Ingredients</label><textarea id="lab" rows="5" placeholder="e.g. Refined wheat flour (maida), sugar, palm oil, invert syrup, salt, raising agents (INS 500), milk solids, emulsifier (INS 322), artificial colour (INS 102)">${esc(LS('lastLabel',''))}</textarea>
 <div class="row"><button class="pri" onclick="decode()">Decode</button><button onclick="document.getElementById('lab').value='Refined wheat flour (maida), sugar, palm oil, invert syrup, salt, milk solids, emulsifier (INS 322), artificial colour (INS 102), cocoa solids';decode()">Try an example</button></div><div id="dec" aria-live="polite"></div>`;
 if(t==='choke')return crumbs([['Tools','#/tools'],['Choking checker']])+`<h1>Food-safety & choking checker</h1><p class="mute">Choose your child’s age to see higher-risk foods and safer ways to serve them.</p><div class="chips">${AGES.map(a=>chip(CK===a[0],a[1],`CK='${a[0]}';render()`)).join('')}</div>${chokeList()}<div class="note warn">Always seat children while eating and supervise. Learn infant and child first aid. Source: <a href="${SRC[REG()].peds[1]}" target="_blank" rel="noopener">${SRC[REG()].peds[0]}</a></div>`;
 return`<h1>Tools</h1><div class="grid2 tools">${[['#/lunchbox','box',T().Box+' builder','Balance a box in 30 seconds'],['#/tools/label','scan','Label decoder','Paste ingredients, see flags'],['#/tools/choke','shield','Choking checker','Safer serving by age'],['#/week','cal','Weekly planner','Auto-plan & drag-drop'],['#/shop','cart','Shopping list','Grouped by aisle'],['#/guides','book','Guides','Step-by-step modules']].map(x=>`<a class="card tap tool" href="${x[0]}"><span class="ticon">${ic(x[1])}</span><b>${x[2]}</b><small class="mute">${x[3]}</small></a>`).join('')}</div>`};
let CK=(kids()[0]||{}).age||'1-3y';
function chokeList(){const yrs={'6-12m':.5,'1-3y':2,'4-8y':6,'9-13y':11,teens:15}[CK];const l=CHOKE.filter(c=>c[1]==='—'||yrs<parseFloat(c[1]));return l.length?`<div class="card">${l.map(c=>`<div class="lrow"><div><b>${c[0]}</b><p class="mute small">${c[2]}</p></div><span class="tag ${c[1]==='—'?'warnt':'bad'}">${c[1]==='—'?'any age':'under '+c[1]}</span></div>`).join('')}</div>`:'<div class="card"><p>No age-specific choking foods flagged at this age. Still eat seated and chew well.</p></div>'}
function decode(){const v=$('#lab').value;SV('lastLabel',v);const hits=[];LABEL_RULES.forEach(r=>{const m=v.match(new RegExp(r.k.source,'gi'));if(m)hits.push([r,[...new Set(m.map(x=>x.toLowerCase()))]])});
 const parts=v.split(/,(?![^(]*\))/).map(x=>x.trim()).filter(Boolean);const firstSugar=parts.findIndex(p=>LABEL_RULES[0].k.test(p));const sugarCount=parts.filter(p=>LABEL_RULES[0].k.test(p)).length;
 $('#dec').innerHTML=v.trim()?`<div class="card"><h2>Summary</h2><p>${parts.length} ingredients. ${firstSugar>-1?`A sugar appears at position <b>${firstSugar+1}</b>${sugarCount>1?` and ${sugarCount} different sugar sources are listed`:''}.`:'No added sugar detected by name.'}</p>
 ${hits.map(([r,m])=>`<div class="lrow"><span class="tag ${r.c}">${r.t}</span><span class="small">${esc(m.join(', '))}</span></div>`).join('')||'<p>No flags found.</p>'}
 <p class="mute small">Name-based screening only; it can miss or over-flag items. Always read the full label and the nutrition table (sugar and sodium per 100 g). ${US()?'US labels list “Added Sugars” separately — use that line.':'FSSAI labels show allergen and veg/non-veg declarations — check them too.'}</p></div>`:''}
/* ===== Foods that heal ===== */
const healNote=()=>`<div class="note warn">${ic('alert')}<span><b>Food supports recovery; it doesn’t treat illness.</b> If your child seems unwell, see a doctor — especially if they’re not drinking, passing very little urine, have no tears, or can’t keep fluids down.</span></div>`;
const healSub=cur=>`<div class="subnav">${[['#/heal','Situations'],['#/heal/day','Time of day'],['#/heal/season','Seasons']].map(x=>`<a href="${x[0]}"${x[0]===cur?' aria-current="page"':''}>${x[1]}</a>`).join('')}</div>`;
const healList=()=>HEAL.filter(h=>(US()?h.us:h.in).length);
V.heal=(sub,id)=>{
 if(sub==='s'){const h=HEAL.find(x=>x.id===id);if(!h||!(US()?h.us:h.in).length)return empty('leaf','Not found','','<a class="btn" href="#/heal">Foods that heal</a>');
  const foods=US()?h.us:h.in,rs=(US()?h.rus:h.rin).map(getR).filter(Boolean),ks=kids().map(k=>k.age);
  return crumbs([['Foods that heal','#/heal'],[h.t]])+`<div class="meta"><span class="tag">${h.g}</span><span class="tag draft">Draft — pending dietitian review</span></div><h1>${h.t}</h1><p class="mute">What’s best to eat and drink.</p>
  <section class="card"><span class="kicker">Best foods & drinks</span><ul class="ticks">${foods.map(f=>`<li>${ic('check')}<span>${esc(f)}</span></li>`).join('')}</ul></section>
  ${rs.length?`<h2 class="sec">Simple recipes</h2><div class="rgrid">${rs.map(rCard).join('')}</div>`:''}
  <section class="card" style="margin-top:var(--s3)"><span class="kicker">Limit or avoid</span><p>${esc(h.limit)}</p></section>
  <h2 class="sec">How much & how often</h2><div class="ages">${AGES.filter(([k])=>h.ages[k]&&h.ages[k]!=='—').map(([k,l])=>`<div class="age${ks.includes(k)?' mine':''}"><b>${l}${ks.includes(k)?' · your child':''}</b><p>${esc(h.ages[k])}</p></div>`).join('')}</div>
  <h2 class="sec">Traditional & popular remedies — evidence check</h2><div class="card">${h.rem.map(r=>`<div class="lrow rem"><div><b>${esc(r[0])}</b><p class="small mute">${esc(r[2])}</p></div><span class="tag ev-${r[1]}">${EVL[r[1]]}</span></div>`).join('')}</div>
  ${healNote()}<p class="small mute">Sources: <a href="${SRC[REG()].diet[1]}" target="_blank" rel="noopener">${SRC[REG()].diet[0]}</a> · <a href="${SRC[REG()].peds[1]}" target="_blank" rel="noopener">${SRC[REG()].peds[0]}</a> · <a href="https://www.who.int/health-topics/diarrhoea" target="_blank" rel="noopener">WHO</a>. Reviewer: to be assigned · Review date: pending.</p>
  <div class="actions"><button onclick="toggleSave('h:${h.id}')">${ic('star',isSaved('h:'+h.id)?'i fill':'i')}${isSaved('h:'+h.id)?'Saved':'Save'}</button><button onclick="share('${esc(h.t)}')">${ic('share')}Share</button></div>`}
 if(sub==='day')return`<h1>Foods that heal</h1>${healSub('#/heal/day')}<p class="mute">When to eat what, through a school day.</p>${WHEN_DAY.map(w=>`<section class="card"><span class="kicker">${w[0]}</span><p>${esc(w[1])}</p><p class="small"><b>Try:</b> ${esc(w[2][REG()])}</p></section>`).join('')}`;
 if(sub==='season')return`<h1>Foods that heal</h1>${healSub('#/heal/season')}<p class="mute">${US()?'US seasons':'Indian seasons, including monsoon'} — what’s fresh and what to watch.</p>${SEASONS[REG()].map(s=>`<section class="card"><span class="kicker">${s[0]}</span><p>${esc(s[1])}</p><p class="small mute">${esc(s[2])}</p></section>`).join('')}`;
 const L=healList(),gs=[...new Set(L.map(h=>h.g))];
 return`<h1>Foods that heal</h1><p class="mute">What’s best to eat and drink, when.</p>${healSub('#/heal')}
 ${gs.map(g=>`<h2 class="sec">${g}</h2><div class="rgrid">${L.filter(h=>h.g===g).map(h=>`<a class="card tap lcard" href="#/heal/s/${h.id}"><span class="grow"><b>${h.t}</b><small class="mute clamp">${esc((US()?h.us:h.in)[0])}</small></span>${ic('right')}</a>`).join('')}</div>`).join('')}
 <p class="small mute" style="margin-top:var(--s5)">Evidence labels: <span class="tag ev-G">Good evidence</span><span class="tag ev-S">Some evidence</span><span class="tag ev-T">Traditional, little evidence</span></p>`};

/* More */
V.more=()=>`<h1>All sections</h1>${[['#/heal','leaf','Foods that heal','What’s best when: sick days, sport, seasons'],['#/experts','users','Hear from the Experts','20 curated expert profiles'],['#/guides','book','Guides','Step-by-step learning'],['#/myths','leaf','Myth library','Common food myths, checked'],['#/tools','tools','Tools','Label decoder, choking checker, '+T().box+' builder'],['#/saved','star','Saved','Your collections'],['#/settings','gear','Settings','Region, theme, profiles, data']].map(x=>`<a class="card tap lcard" href="${x[0]}"><span class="ticon">${ic(x[1])}</span><span class="grow"><b>${x[2]}</b><small class="mute">${x[3]}</small></span>${ic('right')}</a>`).join('')}`;
/* Settings */
V.settings=()=>{const th=LS('theme','system');return`<h1>Settings</h1>
 <section class="card"><h2>Region</h2><div class="chips">${chip(!US(),'India',"setRegion('in')")}${chip(US(),'United States',"setRegion('us')")}</div><p class="mute small">Changes foods, recipes, school notes, units and official sources.</p></section>
 <section class="card"><h2>Units</h2><div class="chips">${['metric','us'].map(u=>chip(LS('units',US()?'us':'metric')===u,u==='us'?'Cups / oz / °F':'Grams / ml / °C',`SV('units','${u}');render()`)).join('')}</div><p class="mute small">Recipes are currently written in the region’s common kitchen units.</p></section>
 <section class="card"><h2>Appearance</h2><div class="chips">${['system','light','dark'].map(t=>chip(th===t,t[0].toUpperCase()+t.slice(1),`SV('theme','${t}');theme();render()`)).join('')}</div></section>
 <section class="card"><h2>Family profiles</h2>${kids().map(k=>`<div class="lrow"><span><b>${esc(k.name)}</b> · ${AGES.find(a=>a[0]===k.age)[1]} · ${k.diet}${k.allergies.length?' · allergies: '+k.allergies.join(', '):''}</span></div>`).join('')||'<p class="mute">No profiles yet.</p>'}<button onclick="SV('draftKids',kids());go('#/onboard/2')">Edit profiles & goals</button></section>
 <section class="card"><h2>Your data</h2><p class="mute small">Everything is stored only in this browser.</p><div class="row"><button onclick="exportData()">${ic('download')}Export JSON</button><button class="danger" onclick="resetAll()">Reset everything</button></div></section>
 <section class="card"><h2>About</h2><p class="small">Dabbawise prototype · ${ans().length} answers · ${recs().length} recipes · ${GUIDES.length} guides · 20 experts. All content is a draft pending qualified expert review. General information only — not medical advice. The name “Dabbawise” is subject to trademark and domain clearance.</p></section>`};
function setRegion(r){SV('region',r);toast(r==='us'?'Switched to United States':'Switched to India');render()}
function exportData(){const d={};Object.keys(localStorage).filter(k=>k.startsWith('dw2_')).forEach(k=>d[k]=localStorage.getItem(k));const b=new Blob([JSON.stringify(d,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='dabbawise-data.json';a.click()}
function resetAll(){modal(`<h2>Reset everything?</h2><p class="mute">Profiles, plans, lists and saved items on this device will be deleted.</p><div class="row end"><button onclick="closeM()">Cancel</button><button class="danger" onclick="Object.keys(localStorage).filter(k=>k.startsWith('dw2_')).forEach(k=>localStorage.removeItem(k));closeM();go('#/onboard/1')">Reset</button></div>`)}
/* Cmd-K */
function openK(){modal(`<div class="kbox"><label class="sr" for="kq">Search Dabbawise</label><input id="kq" autocomplete="off" placeholder="Search answers, recipes, guides, experts, tools…" oninput="kres(this.value)" onkeydown="kkey(event)"><div id="kr" role="listbox"></div></div>`,'top');kres('');setTimeout(()=>$('#kq')?.focus(),30)}
let KI=0;
function kres(q){KI=0;const r=searchAll(q).slice(0,12);const rec=LS('recent',[]);const trend=US()?['juice box','nut-free lunch','picky','granola bar','iron']:['paneer','tiffin','iron','maggi','picky'];
 $('#kr').innerHTML=q.trim()?(r.length?r.map((x,i)=>`<a role="option" class="kitem${i===0?' sel':''}" href="${x.h}" onclick="kpick('${esc(q)}')"><span class="tag">${x.t}</span><span><b>${esc(x.l)}</b><small class="mute"> ${esc(x.d).slice(0,70)}</small></span></a>`).join(''):`<div class="empty small"><p><b>No results for “${esc(q)}”.</b></p><p class="mute">We’ve noted it so the library can grow from real questions.</p></div>`):
 `${rec.length?`<p class="kicker">Recent</p><div class="chips wrap">${rec.map(x=>`<button class="chip" onclick="$('#kq').value='${esc(x)}';kres('${esc(x)}')">${esc(x)}</button>`).join('')}</div>`:''}<p class="kicker">Trending</p><div class="chips wrap">${trend.map(x=>`<button class="chip" onclick="$('#kq').value='${x}';kres('${x}')">${x}</button>`).join('')}</div>`;
 if(q.trim()&&!r.length){const u=LS('unanswered',[]);if(!u.includes(q))SV('unanswered',[...u,q].slice(-50))}}
function kpick(q){const r=LS('recent',[]).filter(x=>x!==q);SV('recent',[q,...r].slice(0,6));closeM(true)}
function kkey(e){const it=$$('.kitem');if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();KI=(KI+(e.key==='ArrowDown'?1:-1)+it.length)%it.length;it.forEach((x,i)=>x.classList.toggle('sel',i===KI));it[KI]?.scrollIntoView({block:'nearest'})}if(e.key==='Enter'&&it[KI]){kpick(e.target.value);location.hash=it[KI].getAttribute('href')}}
/* Modal */
let lastFocus=null;
function modal(h,pos=''){closeM(true);lastFocus=document.activeElement;const m=document.createElement('div');m.className='modal '+pos;m.id='m';m.onclick=e=>e.target===m&&closeM();m.innerHTML=`<div class="sheet" role="dialog" aria-modal="true">${h}</div>`;document.body.append(m);setTimeout(()=>m.querySelector('input,textarea,button,a')?.focus(),20)}
function closeM(silent){const m=$('#m');if(m){m.remove();lastFocus?.focus?.()}}
/* Router */
const TABS=[['today','sun','Today'],['explore','search','Explore'],['meals','meal','Meals'],['heal','leaf','Heal'],['week','cal','My Week']];
const TABOF={a:'explore',myths:'explore',guides:'explore',g:'explore',myths:'explore',more:'explore',r:'meals',experts:'explore',x:'explore',lunchbox:'week',shop:'week',saved:'week',tools:'explore',settings:'',onboard:'',heal:'heal'};
function go(h){location.hash=h}
function theme(){const t=LS('theme','system');document.documentElement.dataset.theme=t==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):t}
let lastRoute='';
function render(){theme();if(!REG())SV('region','in');/* Discovery is open to guests; onboarding is optional and only opens when requested. */
 if(location.hash.startsWith('#/care')){location.replace('#/heal');return}
 const parts=(location.hash.slice(2)||'today').split('/');const name=parts[0];const fn=V[name]||(()=>empty('search','Page not found','That link doesn’t match anything in Dabbawise.','<a class="btn pri" href="#/today">Go to Today</a>'));const tab=TABOF[name]??name;
 const same=lastRoute===location.hash;lastRoute=location.hash;const main=$('#main');
 if(!same&&name!=='onboard'){main.innerHTML='<div class="skel" aria-label="Loading"><i></i><i></i><i></i><i></i></div>';main.setAttribute('aria-busy','true')}
 const draw=()=>{let body;try{body=fn(...parts.slice(1))}catch(err){console.error('Dabbawise view error',name,err);body=empty('alert','Something went wrong','This screen couldn’t load. Error: '+esc(err?.message||'unknown')+'. Your locally saved data has not been changed.','<a class="btn pri" href="#/today">Back to Today</a>')}main.innerHTML=`<div class="view${same?' still':''}">${body}</div><footer class="foot">Dabbawise · ${US()?'United States':'India'} edition · Draft content pending expert review · Not medical advice · Name subject to trademark/domain clearance.</footer>`;main.removeAttribute('aria-busy');
  if(name!=='today'&&name!=='onboard'){const v=main.querySelector('.view');if(v){const bar=document.createElement('nav');bar.className='tpk-quick-nav';bar.setAttribute('aria-label','Main things you can do');bar.innerHTML='<a href="#/week">🥗 Plan meals</a><a href="#/explore">🍎 Check nutrition</a><a href="#/food-truth">🛡 Food Truths</a><a href="#/parent-kitchen">♥ Share recipes</a>';v.prepend(bar)}}
  document.body.classList.toggle('onb-mode',name==='onboard');$$('.tabs a').forEach(a=>a.setAttribute('aria-current',a.dataset.t===tab?'page':'false'));$('#rg').innerHTML=ic('globe')+(US()?'US':'India');
  const h1=main.querySelector('h1');document.title=(h1?h1.textContent+' · ':'')+'The Parent Kitchen';if(!same){scrollTo(0,0);h1?.setAttribute('tabindex','-1');h1?.focus({preventScroll:true})}};
 same||name==='onboard'?draw():setTimeout(draw,90)}
function shell(){document.body.insertAdjacentHTML('afterbegin',`<a class="skip" href="#main" onclick="event.preventDefault();$('#main').focus()">Skip to content</a>
 <aside class="side"><a class="logo" href="#/today">dabba<i>wise</i></a><nav class="tabs" aria-label="Main">${TABS.map(t=>`<a href="#/${t[0]}" data-t="${t[0]}">${ic(t[1])}<span>${t[2]}</span></a>`).join('')}</nav>
 <div class="sidex"><a href="#/more">${ic('more')}All sections</a><a href="#/experts">${ic('users')}Experts</a><a href="#/guides">${ic('book')}Guides</a><a href="#/tools">${ic('tools')}Tools</a><a href="#/settings">${ic('gear')}Settings</a></div></aside>
 <header class="top"><a class="logo m" href="#/today" aria-label="Dabbawise home">dabba<i>wise</i></a><span class="sp"></span><button class="kbtn" onclick="openK()" aria-label="Search (Ctrl or Cmd K)">${ic('search')}<span class="kl">Search</span><kbd>⌘K</kbd></button><button id="rg" class="pill" onclick="go('#/settings')" aria-label="Region: change in settings"></button><a class="btn icon gear" href="#/settings" aria-label="Settings">${ic('gear')}</a></header>
 <main id="main" tabindex="-1"></main><div id="toast" role="status" aria-live="polite"></div>`)}
shell();addEventListener('hashchange',render);
addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openK()}if(e.key==='Escape'&&$('#m'))closeM();if(e.key==='/'&&!/INPUT|TEXTAREA/.test(document.activeElement.tagName)){e.preventDefault();openK()}});
matchMedia('(prefers-color-scheme: dark)').addEventListener?.('change',theme);
if('serviceWorker' in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('sw.js').catch(()=>{});
/* render() is called by v6/ui6.js */
